package ci

import (
	"bytes"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// generated_skip_test.go is the generated-file exemption of the line linters
// (schemas/README.md). A package generated by the schema compiler is checked by
// `make schemawire-check` (go generate, then git diff --exit-code): its lines are
// the compiler's, not this repository's, so a line linter reading them finds the
// compiler's words (a method named for whitespace, its own docs' paths) and would
// have every generated line allowlisted one by one. A file is generated when it
// carries Go's standard header (https://go.dev/s/generatedcode): a line
// `// Code generated ... DO NOT EDIT.` before the package clause. A hand-written
// file with the same lines and no header is linted as before; the hand-written
// generate.go beside each generated package is linted too, and the module path of
// its `//go:generate go run <module>@<version>` pin reads like an import.

// schemawireFixtureDir holds the fixture: one generated file and one hand-written
// generate.go, as the first generated package will hold them.
const schemawireFixtureDir = "testdata/schemawire_fixture"

// generatedMarker is the substring every generated header carries, the cheap
// test before a parse.
var generatedMarker = []byte("DO NOT EDIT")

// isGeneratedGo reports whether src is a generated Go file by Go's standard
// rule, which go/ast implements: the header comment precedes the package clause.
// Only the package clause and the comments before it are parsed, and a file with
// no "DO NOT EDIT" at all is not parsed.
func isGeneratedGo(src []byte) bool {
	if !bytes.Contains(src, generatedMarker) {
		return false
	}
	f, err := parser.ParseFile(token.NewFileSet(), "", src, parser.PackageClauseOnly|parser.ParseComments)
	if f == nil || err != nil {
		return false
	}
	return ast.IsGenerated(f)
}

// TestGeneratedFilesSkippedByLineLinters holds every line linter that reads Go
// source as text (the generality guardrail and the named-path rule) to the
// exemption: the generated fixture is skipped, the same lines without the header
// are read and found, and the hand-written generate.go's pin line is no finding.
func TestGeneratedFilesSkippedByLineLinters(t *testing.T) {
	t.Parallel()

	generated, err := os.ReadFile(filepath.Join(schemawireFixtureDir, "pongwire.go"))
	require.NoError(t, err)
	header, body, ok := bytes.Cut(generated, []byte("\n"))
	require.True(t, ok)
	require.Contains(t, string(header), "DO NOT EDIT.", "the fixture opens with Go's generated header")
	// The hand-written twin is the same lines with the header swapped for an
	// ordinary comment, so the header is the only difference between the two.
	handWritten := append([]byte("// Written by hand from the compiler's output.\n"), body...)
	pin, err := os.ReadFile(filepath.Join(schemawireFixtureDir, "generate.go"))
	require.NoError(t, err)

	require.True(t, isGeneratedGo(generated), "the header before the package clause marks the file generated")
	require.False(t, isGeneratedGo(handWritten), "no header, no exemption")
	require.False(t, isGeneratedGo(pin), "generate.go is hand-written")
	late := append(append([]byte{}, body...), header...)
	require.False(t, isGeneratedGo(append(late, '\n')), "a header after the package clause is not Go's header")

	const (
		genRel  = "pkg/friend/pongwire/pongTableJson.go"
		handRel = "pkg/friend/pongwire/pongTableJsonHand.go"
		pinRel  = "pkg/friend/pongwire/generate.go"
	)

	t.Run("generality", func(t *testing.T) {
		t.Parallel()
		hits := scanGenerality([]GeneralitySourceFile{
			{Rel: genRel, Src: generated},
			{Rel: handRel, Src: handWritten},
			{Rel: pinRel, Src: pin},
		})
		byFile := map[string]int{}
		for _, h := range hits {
			byFile[h.rel]++
		}
		assert.Zero(t, byFile[genRel], "the generated file is skipped: %v", hits)
		assert.Equal(t, 3, byFile[handRel], "the hand-written twin's three `space` lines are still findings: %v", hits)
		assert.Zero(t, byFile[pinRel], "the pin's module path reads like an import: %v", hits)
	})

	t.Run("generality pin is the only exemption in generate.go", func(t *testing.T) {
		t.Parallel()
		named := append(append([]byte{}, pin...), []byte("\n// Pinned for mas-bandwidth.\n")...)
		hits := scanGenerality([]GeneralitySourceFile{{Rel: pinRel, Src: named}})
		require.Len(t, hits, 1, "a name outside the go:generate module path still counts: %v", hits)
		assert.Equal(t, "mas-bandwidth", hits[0].tok)
	})

	t.Run("named paths", func(t *testing.T) {
		t.Parallel()
		tree := &repoTreeIndex{Files: []*treeFile{
			{Rel: genRel, Go: true, Src: generated},
			{Rel: handRel, Go: true, Src: handWritten},
			{Rel: pinRel, Go: true, Src: pin},
		}}
		read := map[string]bool{}
		var names []string
		for _, f := range namedPathSources(tree) {
			read[f.Rel] = true
			for _, line := range strings.Split(string(f.Src), "\n") {
				names = append(names, namedPathsIn(line)...)
			}
		}
		assert.False(t, read[genRel], "the generated file is not read")
		assert.True(t, read[handRel], "the hand-written twin is read")
		assert.True(t, read[pinRel], "generate.go is read")
		assert.ElementsMatch(t, []string{"docs/SPEC-TABLES.md", "internal/tablenames"}, names,
			"the twin's two paths into the compiler's tree are still read")
	})
}
